  "abo\\s+(?:and\\s+rh|antibod\\p{L}*|agglutin\\p{L}*|samples?|series|groups?|typing|compatib\\p{L}*|antigens?|rh|-?incompatib\\p{L}*)|d'?abo",
  "doo[\\s-]*wops?",
  "gobbledy[\\s-]*gook|gobbledygook",
  "coons?\\s+(?:et\\s+al|\\(|,\\s*\\d{4}|rapids|hound|dog|hunting|skin\\s+cap)|coon\\s*hounds?|coonskin",
  "spic?k?\\s+(?:and|&|n'?)\\s+span",
  "(?:smok(?:e|es|ed|ing)|light(?:s|ed|ing)?(?:\\s+up)?|roll(?:s|ed|ing)?(?:\\s+up)?|packet\\s+of|pack\\s+of|having\\s+a|have\\s+a|need\\s+a|quick|cheeky|last)\\s+(?:a\\s+)?fags?|fags?\\s+(?:end|ends|break|breaks|packet|packets|butt|butts|ash|lighter|machine)",
  "(?:auto|manual|automatic|the|my|your|his|her|car'?s?|truck'?s?)\\s+tranny\\s+(?:fluid|cooler|rebuild|shop|mount|pan|filter|swap|slip|slips|slipping|went|is\\s+(?:shot|slipping|toast|gone|dead)|problems?|issues?|line|lines|oil|gear|gears)|tranny\\s+(?:fluid|cooler|rebuild|mount|pan|filter|swap|slip|slipping|shop|oil|gears?|lines?)",
  "(?:island\\s+of|isle\\s+of|on|in|to|from|visit(?:ed|ing)?)\\s+lesbos|lesbos,?\\s+(?:island|greece|camp|refugee)",
