const pack = {
  format: 'bnet-pack/1',
  id: 'core',
  name: 'BNet Core',
  version: '2026.10.27',
  description: 'Built-in English list: slurs (with disguise handling), groups x claims (dehumanising, stereotypes, threats, exclusion), extremist codes and slogans.',
  groups, predicates, prefixes, slurs, phrases, allow
};

// Write the external rule list: rules/core.txt (one rule per line, ad-blocker style).
const Lists = require('../src/lists.js');
let txt = Lists.fromPack(pack, { title: 'BNet Core', version: pack.version, description: pack.description, expires: '7 days' });
const defs = [['COP', COP], ['MODAL', MODAL], ['OF', OF]];
for (const [name, src] of defs) txt = txt.split(src).join('{' + name + '}');
const head = txt.split('\n\n')[0];
const rest = txt.slice(head.length);
txt = head + '\n!\n! One rule per line. Lines starting with ! are comments. Syntax help: BNet settings > Rule lists.\n\n'
  + '! Reusable pieces\n' + defs.map(([n, src]) => 'define ' + n + ' ' + src).join('\n') + '\n' + rest;
const out = path.join(__dirname, '..', 'rules', 'core.txt');
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, txt);
// Round-trip check: the text list must compile to the same rules as the source.
const E = require('../src/engine.js');
const parsed = Lists.parse(txt, 'core');
if (parsed.errors.length) { console.error(parsed.errors.slice(0, 5)); process.exit(1); }
const a = E.compile([pack]), b = E.compile([parsed.data]);
if (a.errors.length) { console.error(a.errors.slice(0, 5)); process.exit(1); }
console.log('wrote', out, 'lines', txt.split('\n').length, 'rules', a.count, b.count, 'bytes', txt.length);
if (a.count !== b.count) { console.error('round-trip mismatch'); process.exit(1); }
